import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Relativity — Spacetime & Causality","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science/relativity.md","filePath":"docs/science/relativity.md"}`),a={name:`docs/science/relativity.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="relativity-—-spacetime-causality" tabindex="-1">Relativity — Spacetime &amp; Causality <a class="header-anchor" href="#relativity-—-spacetime-causality" aria-label="Permalink to “Relativity — Spacetime &amp; Causality”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorem:</strong> <code>Relativity.lean</code> (7 theorems, all <code>by decide</code>)</p><p>Nothing exceeds <em>c</em> (the cosmic speed limit). Light rides the null cone (interval = 0). The invariant interval classifies events as timelike (causally connected) or spacelike (no causal link without FTL). The Lorentz factor follows a Pythagorean triangle: β = 5/13 → γ = 13/12. Moving clocks dilate and lengths contract. Rest energy is E = mc².</p><p><strong>Why sealed:</strong> Pure arithmetic on spacetime geometry. The Pythagorean scaling is exact. No paradox, no experiment needed — special relativity as decidable facts.</p><hr><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p><strong>What relativity CANNOT prove:</strong></p><ul><li>Whether time &quot;really&quot; passes or is illusion (that&#39;s metaphysics of time)</li><li>Why <em>c</em> is the speed limit (that&#39;s quantum field theory, not relativity)</li><li>Whether spacetime is fundamental or emergent (that&#39;s cosmology)</li><li>What causality &quot;means&quot; beyond &quot;cone structure&quot; (philosophy of causation)</li></ul><p><strong>Honest scope:</strong> Relativity seals the GEOMETRY of spacetime. It does not settle whether spacetime is &quot;real&quot; or &quot;just math&quot; or &quot;emergent from something else.&quot;</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>Does relativity eliminate free will and genuine causation?</em></p><p><strong>The Trinity:</strong></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>Causality is strictly defined: event A causes B only if A is in B&#39;s past light cone. The interval is invariant — all observers agree on the causal structure.</td><td>Whether causation is &quot;real&quot; or &quot;only correlations&quot;; whether the light cone is &quot;all there is&quot; to causation; whether determinism is true</td></tr><tr><td><strong>Honest Boundary</strong></td><td>Relativity eliminates <em>acausal</em> influence (no FTL signals). It does NOT eliminate free will — it just says: if you choose, your choice propagates at ≤<em>c</em>.</td><td>Whether your choice is &quot;free&quot; (libertarian vs compatibilist); whether the deterministic structure of physics negates agency; whether meaning survives determinism</td></tr><tr><td><strong>Metaphysical</strong></td><td>If all events are determined by prior light cone conditions, is free will an illusion? Does knowing <em>c</em> is absolute eliminate the possibility of genuine choice?</td><td>Whether determinism ≠ fatalism; whether statistical mechanics&#39; open futures preserve choice; whether meaning requires indeterminism</td></tr></tbody></table><p><strong>The court decides:</strong> Relativity seals the speed limit and causal structure. Philosophy settles whether you are free. The math cannot answer that.</p><hr><h2 id="read-the-sealed-proof" tabindex="-1">Read the Sealed Proof <a class="header-anchor" href="#read-the-sealed-proof" aria-label="Permalink to “Read the Sealed Proof”">​</a></h2><p><a href="./../../lean/Relativity.lean">Link to Relativity.lean</a></p><ul><li><code>nothing_exceeds_c</code></li><li><code>light_rides_null_cone</code></li><li><code>invariant_interval_timelike_or_spacelike</code></li><li><code>lorentz_factor_pythagorean</code></li><li><code>time_dilation_length_contraction</code></li><li><code>rest_energy_equals_mc_squared</code></li></ul><p>Each proven <code>by decide</code>.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>If relativity makes causality purely geometric (cone structure, no FTL), then:</p><ol><li>Is &quot;free will&quot; just freedom from external causation (libertarian), or does determinism eliminate it?</li><li>Can you make a genuine choice in a deterministic universe?</li><li>Does the light cone eliminate meaningful causation or just acausal magic?</li></ol><p><strong>These are open.</strong> Relativity does not answer them. Only you can.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};